mutations.before:
const scenes = new Set(
  t.beats.flatMap((beat) => (beat.background !== undefined ? [beat.background] : [])),
);
if (scenes.size > MAX_SCENES) {
  return `copy.timeline.beats name more than ${MAX_SCENES} distinct backgrounds (max ${MAX_SCENES}).`;
}

beats: state.timeline.beats.map((beat) => ({
  text: beat.text,
  weight: beat.weight,
  // VE5a: written back only when the beat names one — a draft that never
  // had a scene must serialise exactly as it did without the field (D3).
  ...(beat.background !== undefined ? { background: beat.background } : {}),
})),

mutations.after:
beats: state.timeline.beats.map((beat) => ({
  text: beat.text,
  weight: beat.weight,
})),
